<?php
require_once 'inc/db.php'; require_once 'inc/auth.php';
$id=(int)($_GET['id']??0); $msg=$msge='';
$load=function() use($db,$id){$s=$db->prepare('SELECT r.*,dt.type_name,u.firstname,u.lastname FROM tbl_road_reports r JOIN tbl_damage_types dt ON dt.type_id=r.damage_type_id JOIN tbl_users u ON u.user_id=r.reported_by WHERE r.report_id=?');$s->execute([$id]);return $s->fetch(PDO::FETCH_ASSOC);};
$report=$load(); if(!$report || ((int)$_SESSION['role_id']===4 && (int)$report['reported_by']!==(int)$_SESSION['user_id'])) { http_response_code(404); die('Report not found.'); }
if($_SERVER['REQUEST_METHOD']==='POST' && can_manage_reports()){
 $new=$_POST['status']??''; $notes=trim($_POST['notes']??''); $allowed=['Pending','Under Review','Approved','In Progress','Resolved','Rejected'];
 if(in_array($new,$allowed,true)){$db->beginTransaction();try{$s=$db->prepare('UPDATE tbl_road_reports SET status=? WHERE report_id=?');$s->execute([$new,$id]);$s=$db->prepare('INSERT INTO tbl_maintenance_updates(report_id,updated_by,old_status,new_status,notes) VALUES(?,?,?,?,?)');$s->execute([$id,$_SESSION['user_id'],$report['status'],$new,$notes]);notify_user($db,(int)$report['reported_by'],'Report status updated',$report['report_code'].' is now '.$new.'.',$id);$db->commit();audit_log($db,'REPORT_STATUS_UPDATED',$report['report_code'].' changed from '.$report['status'].' to '.$new);$msg='Status and maintenance notes saved.';$report=$load();}catch(Throwable $e){$db->rollBack();$msge='The update could not be saved.';}}
}
$s=$db->prepare('SELECT m.*,u.firstname,u.lastname FROM tbl_maintenance_updates m JOIN tbl_users u ON u.user_id=m.updated_by WHERE m.report_id=? ORDER BY m.updated_at DESC');$s->execute([$id]);$updates=$s->fetchAll(PDO::FETCH_ASSOC);
$page_title='Report '.$report['report_code'];$breadcrumb='Reports'; include 'inc/links.php';include 'inc/header.php';
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php'; ?><section role="main" class="content-body"><?php include 'inc/inner-header.php'; ?>
<?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;if($msge):?><div class="alert alert-danger"><?php echo e($msge);?></div><?php endif;?>
<div class="row"><div class="col-md-8"><section class="panel"><header class="panel-heading"><span class="detail-code"><?php echo e($report['report_code']); ?> &middot; <?php echo date('d M Y H:i',strtotime($report['reported_at'])); ?></span><h2 class="panel-title"><?php echo e($report['type_name']); ?> at <?php echo e($report['location_name']); ?></h2></header><div class="panel-body">
<?php if($report['image_path']):?><img class="report-image report-detail-image" src="<?php echo e($report['image_path']);?>" alt="Road damage evidence"><?php else:?><div class="well text-center text-muted"><i class="fa fa-image fa-3x"></i><br>No image attached</div><?php endif;?>
<div class="row report-meta"><div class="col-sm-6"><p><strong>Severity:</strong> <?php echo severity_label($report['severity']);?></p><p><strong>Status:</strong> <?php echo status_label($report['status']);?></p><p><strong>Priority:</strong> <?php echo (int)$report['priority_score'];?>/100</p><p><strong>Classification:</strong> Engineer validation required</p></div><div class="col-sm-6"><p><strong>Reporter:</strong> <?php echo e($report['firstname'].' '.$report['lastname']);?></p><p><strong>Province:</strong> <?php echo e($report['province']);?></p><p><strong>District / sector:</strong> <?php echo e($report['district'].' / '.$report['sector']);?></p><p><strong>GPS:</strong> <?php echo e($report['latitude'].', '.$report['longitude']);?></p></div></div>
<h4>Description</h4><p><?php echo nl2br(e($report['description']?:'No description supplied.'));?></p>
</div></section></div><div class="col-md-4">
<?php if(can_manage_reports()):?><section class="panel"><header class="panel-heading"><h2 class="panel-title"><i class="fa fa-wrench"></i> Validate & Update</h2></header><div class="panel-body"><form method="post"><div class="form-group"><label>Status</label><select name="status" class="form-control"><?php foreach(['Pending','Under Review','Approved','In Progress','Resolved','Rejected'] as $v):?><option <?php echo $report['status']===$v?'selected':'';?>><?php echo e($v);?></option><?php endforeach;?></select></div><div class="form-group"><label>Assessment / maintenance notes</label><textarea name="notes" class="form-control" rows="4" required></textarea></div><button class="btn btn-danger btn-block">Save Update</button></form></div></section><?php endif;?>
<section class="panel"><header class="panel-heading"><h2 class="panel-title">Activity History</h2></header><div class="panel-body"><div class="timeline-mini"><?php foreach($updates as $u):?><div><strong><?php echo e($u['new_status']);?></strong><br><span><?php echo e($u['notes']);?></span><small><?php echo e($u['firstname'].' '.$u['lastname']);?> · <?php echo date('d M Y H:i',strtotime($u['updated_at']));?></small></div><?php endforeach;?><?php if(!$updates):?><p class="text-muted">No maintenance updates yet.</p><?php endif;?></div></div></section></div></div>
</section></div><?php include 'inc/scripts.php';?>
